import{_ as e,o as r,c as a,a5 as i}from"./chunks/framework.BZzouRtU.js";const s="/study/images/graphics/frame-pacing-intervals.svg",n="/study/images/graphics/frame-pacing-pipeline.svg",P=JSON.parse('{"title":"平均60 FPSでもカクつくのはなぜか — フレームタイムとフレームペーシング","description":"","frontmatter":{"title":"平均60 FPSでもカクつくのはなぜか — フレームタイムとフレームペーシング","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"同じ平均FPSでも画面が切り替わる間隔で見え方が変わる。CPUの処理、GPUの描画、画面への提示をタイムラインで分け、カクつきが起きた区間を調べる。","aliases":["フレームタイム","frame time","フレームペーシング","frame pacing","スタッター","stutter","Present","VSync","p99","PresentMon"],"verification":"Android Frame Pacing、DXGI Present、PresentMon 2.6.0のCSV列、PIX Timing Capturesの公式資料に照合（2026-11-06）"}},"headers":[],"relativePath":"graphics/optimization/frame-pacing.md","filePath":"graphics/optimization/frame-pacing.md"}'),o={name:"graphics/optimization/frame-pacing.md"};function d(l,t,g,p,c,h){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="平均60-fpsでもカクつくのはなぜか-—-フレームタイムとフレームペーシング" tabindex="-1">平均60 FPSでもカクつくのはなぜか — フレームタイムとフレームペーシング <a class="header-anchor" href="#平均60-fpsでもカクつくのはなぜか-—-フレームタイムとフレームペーシング" aria-label="Permalink to &quot;平均60 FPSでもカクつくのはなぜか — フレームタイムとフレームペーシング&quot;">​</a></h1><p>カメラを一定の速さで動かしていても、画面が一瞬止まり、そのあと大きく進むことがあります。1秒あたりに表示されたフレーム数が同じでも、次の絵が出るまでの時間は揃っているとは限りません。<strong>フレームペーシング</strong>は、ゲームの更新・描画と表示側のタイミングを合わせ、画面の切り替わりを狙った間隔に整えることです。<a href="https://developer.android.com/games/sdk/frame-pacing#background" target="_blank" rel="noreferrer">Android Frame Pacingの仕組み</a></p><h2 id="同じ平均60-fpsで、画面の切り替わり方を比べる" tabindex="-1">同じ平均60 FPSで、画面の切り替わり方を比べる <a class="header-anchor" href="#同じ平均60-fpsで、画面の切り替わり方を比べる" aria-label="Permalink to &quot;同じ平均60 FPSで、画面の切り替わり方を比べる&quot;">​</a></h2><p>固定120 Hzの仮想ディスプレイは約8.33 msごとに更新します。60 FPSを等間隔で表示するには、新しい絵に切り替える間隔を2更新分の約16.67 msにします。ここでは、<strong>ある絵に切り替わってから次の絵に切り替わるまでの時間</strong>を表示間隔と呼びます。同じ絵のままリフレッシュしても、新しい表示フレームには数えません。</p><p>2秒間の表示を二つ用意します。等間隔の例では全120フレームをそれぞれ2更新分だけ表示します。スパイクのある例では、31枚目と91枚目をそれぞれ6更新分（50 ms）表示し、その直後の4フレームは1更新分（約8.33 ms）ずつにします。どちらも合計は240更新分で、120フレーム ÷ 2秒 = <strong>60 FPS</strong>です。50 ms同じ絵が続くところでは動きが一瞬止まったように見え、その次の絵でまとめて進みます。</p><figure class="study-figure"><img src="'+s+'" alt="仮想120 Hzで500 msから583.33 msまでを比較する。上段は2更新ごとにフレーム31から35へ切り替わる。下段は31が6更新続き、その後の32から35は1更新ずつで切り替わる。両段とも10更新の間に5フレームを表示する。" width="760" height="302" loading="lazy"><figcaption>2秒間のうち、最初のスパイク周辺を拡大。横幅は表示していた時間です。<a href="/study/images/graphics/frame-pacing-intervals.svg" target="_blank" rel="noopener noreferrer">表示間隔の図を拡大</a></figcaption></figure><table tabindex="0"><thead><tr><th>指標</th><th style="text-align:right;">等間隔</th><th style="text-align:right;">スパイクあり</th></tr></thead><tbody><tr><td>平均FPS</td><td style="text-align:right;">60</td><td style="text-align:right;">60</td></tr><tr><td>平均表示間隔</td><td style="text-align:right;">16.67 ms</td><td style="text-align:right;">16.67 ms</td></tr><tr><td>p99表示間隔</td><td style="text-align:right;">16.67 ms</td><td style="text-align:right;">50.00 ms</td></tr><tr><td>最長の表示間隔</td><td style="text-align:right;">16.67 ms</td><td style="text-align:right;">50.00 ms</td></tr><tr><td>60 FPSの目安（約16.67 ms）を超えた間隔</td><td style="text-align:right;">0回</td><td style="text-align:right;">2回</td></tr></tbody></table><p>表は表示間隔を最後まで観測できた120フレームで集計しています。平均FPSはフレーム数を経過秒数で割って求めます。p99（99パーセンタイル）は、ここでは間隔を短い順に並べ、<code>ceil(0.99 × 件数)</code> 番目の値を取ります。120件なら119番目なので、50 msの間隔が1回だけの場合はp99に現れません。どの場面で何度起きたかを調べるには、最長値と時系列も見ます。</p><p>ブラウザ実践では、同じ時刻を使った二つの動きとグラフを見比べ、再生を止めてスパイクの前後を調べられます。数値は仮想120 Hzのモデルから計算します。<a href="/study/practice/graphics/frame-pacing-observation.html">表示間隔を見比べる実践</a></p><h2 id="cpu、gpu、ディスプレイは別の時刻で動く" tabindex="-1">CPU、GPU、ディスプレイは別の時刻で動く <a class="header-anchor" href="#cpu、gpu、ディスプレイは別の時刻で動く" aria-label="Permalink to &quot;CPU、GPU、ディスプレイは別の時刻で動く&quot;">​</a></h2><p>ゲームはCPUで入力や状態を更新し、GPUに描画コマンドを送ります。GPUがその絵を描いている間に、CPUが次のフレームの準備を始めることもあります。アプリの <code>Present()</code> などの呼び出しは表示への要求です。描画完了やOSの合成、提示方式によって、実際に画面が切り替わる時刻は後になります。キューに入った絵が提示方式によって表示されずに破棄される場合もあります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/dxgi/nf-dxgi-idxgiswapchain-present#flip-presentation-model-queue" target="_blank" rel="noreferrer">DXGI Presentとフリップキュー</a></p><figure class="study-figure"><img src="'+n+'" alt="固定60 Hzの例。CPUがフレームBの描画を依頼し、GPUがBを描いている間にCPUがCの準備を始める。Bが16.67 msの更新に間に合わないので画面はAのまま。33.33 msでB、50 msでCが表示される。" width="760" height="358" loading="lazy"><figcaption>固定60 Hzの例では、Bが予定した更新に間に合わず、Aが2更新分表示されます。<a href="/study/images/graphics/frame-pacing-pipeline.svg" target="_blank" rel="noopener noreferrer">CPU・GPU・画面の図を拡大</a></figcaption></figure><p>図は固定リフレッシュレートで、更新の境目に絵を切り替える簡略モデルです。Bを表示する予定の時刻にGPUの仕事が終わっていなければ、画面にはAがもう1更新分残ります。実機ではVSync、可変リフレッシュレート（VRR）、OSの合成や提示方式によってタイミングが変わります。例えばVRRは対応範囲内で更新周期を変えられるので、固定周期のように表示間隔を一律に数える方法は適しません。<a href="https://developer.android.com/games/sdk/frame-pacing#background" target="_blank" rel="noreferrer">Androidの表示パイプライン</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddxgi/variable-refresh-rate-displays" target="_blank" rel="noreferrer">DXGIの可変リフレッシュレート</a></p><p>「フレームタイム」と書かれたグラフでは、先に何から何まで測った値かを確かめます。</p><table tabindex="0"><thead><tr><th>どの時間か</th><th>測る範囲</th><th>分かること</th></tr></thead><tbody><tr><td>CPU側のフレーム間隔</td><td>このフレームのCPU処理開始から次の開始まで</td><td>CPU側の更新ペース。実行に加え待ちも入る</td></tr><tr><td>CPU・GPUの実行時間</td><td>各プロセッサーでフレームの仕事をしていた区間</td><td>どの処理が長いか。CPUとGPUで区間が重なる場合がある</td></tr><tr><td>Present間隔</td><td>アプリが表示要求を出してから次の要求まで</td><td>アプリ側の提示要求のペース</td></tr><tr><td>表示間隔</td><td>この絵が表示されてから次の絵に切り替わるまで</td><td>絵が更新された間隔。画面側のカクつきを追う手掛かり</td></tr></tbody></table><h2 id="windowsでカクついた区間を追う" tabindex="-1">Windowsでカクついた区間を追う <a class="header-anchor" href="#windowsでカクついた区間を追う" aria-label="Permalink to &quot;Windowsでカクついた区間を追う&quot;">​</a></h2><ol><li><strong>再現条件を揃える。</strong> 同じビルド、カメラ経路、画面設定で記録します。リフレッシュレート、VSync、VRR、FPS制限を控え、読み込み直後と再訪時で挙動が違う場合は両方記録します。</li><li><strong>表示が長く止まった区間を見つける。</strong> PresentMonのCSVを対象プロセスとスワップチェーンで絞ります。バージョン2.6.0の既定CSVでは、<code>MsBetweenDisplayChange</code> が、現在の絵に切り替わるまでに<strong>直前の絵</strong>が表示されていた時間です。数値のある行を時系列で見て、表示要求の間隔を示す <code>MsBetweenPresents</code> と比べます。要求の間隔が安定していて表示側の間隔が跳ねる場合は、GPUや表示経路での遅れを調べます。同じCSVでCPU側のフレーム間隔は <code>MsBetweenAppStart</code>、CPUとGPUの稼働時間は <code>MsCPUBusy</code> と <code>MsGPUBusy</code> です。<code>--v2_metrics</code> を指定したCSVでは、各行の絵の表示時間は <code>DisplayedTime</code> に出ます。<a href="https://github.com/GameTechDev/PresentMon/blob/v2.6.0/README-ConsoleApplication.md#csv-columns" target="_blank" rel="noreferrer">PresentMon 2.6.0の指標定義</a> · <a href="https://github.com/GameTechDev/PresentMon/blob/v2.6.0/PresentMon/CsvOutput.cpp#L530-L605" target="_blank" rel="noreferrer">CSVヘッダーの実装</a></li><li><strong>前後の普通のフレームと比較する。</strong> Direct3D 12なら、PIXのTiming CaptureでCPUスレッドとGPUキューを同じ時刻軸に並べます。CPU側で長いイベントや待ちがないか、GPU側で描画・コピーの区間が延びていないか、送信からGPUの実行開始までの待ちが増えていないかを順に見ます。CPUとGPUは並行して進むため、両方の実行時間を足しても表示間隔にはなりません。<a href="https://learn.microsoft.com/en-us/windows/pix/timing-captures/timing-captures-overview" target="_blank" rel="noreferrer">PIX Timing Captures</a></li><li><strong>原因候補を一つ変え、同じ条件で計り直す。</strong> 例えばマップの境目でだけCPUの待ちが増えるなら、ファイル読み込みのマーカーと待ち始めの時刻を照らし合わせます。CPUとGPUの仕事量が普段通りなら、表示キューの待ちや提示方式の変化を確認します。修正前後は平均FPSに加え、同じ場面で表示間隔のスパイクが短くなったか、回数が減ったかを比べます。<a href="/study/graphics/optimization/basics.html">GPU最適化の基礎</a></li></ol><p>描画が終わった絵をどの順番で出すか、表示の途中で絵を替えると何が見えるかは、<a href="/study/graphics/optimization/swap-chain-and-vsync.html">スワップチェーンとVSync</a>で扱います。</p><p>関連項目は<a href="/study/guide/low-level/input-and-game-loop.html">入力とゲームループ</a>と<a href="/study/graphics/optimization/tools.html">デバッグ・プロファイリングツール</a>です。</p>',19)])])}const f=e(o,[["render",d]]);export{P as __pageData,f as default};
